// Compact display identities generated by scripts/build-expanded-registry.py; provenance lives in token-registry.merged.json.
import registry from '../data/token-registry.engine.json' with { type: 'json' };
import { check, decimal } from './util.js';
const NETWORKS=Object.freeze({'1':{name:'Ethereum',symbol:'ETH'},'56':{name:'BNB Smart Chain',symbol:'BNB'},'42161':{name:'Arbitrum One',symbol:'ETH'},'8453':{name:'Base',symbol:'ETH'},'10':{name:'OP Mainnet',symbol:'ETH'},'137':{name:'Polygon PoS',symbol:'POL'},'100':{name:'Gnosis',symbol:'xDAI'},'43114':{name:'Avalanche C-Chain',symbol:'AVAX'}});
const identity=(family,chainId,address)=>[family,chainId??'',family==='evm'?address.toLowerCase():address].join(':');
// The bundled registry is one string of tab separated rows, newline separated:
// networkIndex, address, name, symbol, decimals, icon, programIndex. It is split
// on first use, so a fresh VM that only signs a PSBT or a message pays nothing
// for thousands of token identities it will never look at.
let entries;
const index=()=>entries??=new Map(registry.assets.split('\n').map(row=>{
  const [network,assetAddress,name,symbol,decimals,icon,program]=row.split('\t');
  const [chainFamily,chainId]=registry.networks[+network];
  const asset={chainFamily,...(chainId?{chainId}:{}),assetAddress,name,symbol,decimals:+decimals,icon,
    ...(program==='-1'?{}:{tokenProgram:registry.programs[+program]})};
  return [identity(chainFamily,chainId,assetAddress),Object.freeze(asset)];
}));
export function evmNetwork(chainId) { const id=String(chainId);check(NETWORKS[id],'NETWORK','Unsupported network');return {chainId:id,...NETWORKS[id]}; }
export function lookupToken(chainFamily,chainId,assetAddress,rawAmount,tokenProgram) {
  const asset=index().get(identity(chainFamily,chainId,assetAddress));if(!asset)return undefined;
  if(tokenProgram&&asset.tokenProgram&&asset.tokenProgram!==tokenProgram)return undefined;
  const result={...asset};if(rawAmount!==undefined){result.rawAmount=String(rawAmount);result.displayAmount=decimal(rawAmount,asset.decimals);}return result;
}
export const tokenRegistryVersion=registry.registryVersion;
export const tokenRegistrySize=registry.assetCount;
